import { useEffect, useState } from 'react'
import { API_BASE, fetchJson } from '../../design-lab/shared/api'

const POLL_MS = 5000

// GET /api/arduino-status → {connected, port, message}
export function useArduinoSensor({ demo = 'auto' } = {}) {
  const [state, setState] = useState({ connected: null, port: null, message: null })

  useEffect(() => {
    if (demo === 'forced') {
      setState({ connected: true, port: 'DEMO', message: 'Demo sensor link' })
      return undefined
    }
    let cancelled = false
    const load = async () => {
      try {
        const data = await fetchJson(`${API_BASE}/api/arduino-status`)
        if (!cancelled) setState({ connected: Boolean(data.connected), port: data.port || null, message: data.message || null })
      } catch {
        if (!cancelled) setState({ connected: null, port: null, message: 'unreachable' })
      }
    }
    load()
    const timer = setInterval(load, POLL_MS)
    return () => {
      cancelled = true
      clearInterval(timer)
    }
  }, [demo])

  return state
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { API_BASE, fetchJson } from '../../design-lab/shared/api'
import { demoDetections } from './demoExtras'

const POLL_MS = 10000

export function detectionImageUrl(filename) {
  return filename ? `${API_BASE}/api/images/${encodeURIComponent(filename)}` : null
}

// Normalized event object from a raw /api/detections item.
export function adaptDetection(raw, index) {
  const ts = raw.timestamp ? new Date(raw.timestamp) : null
  return {
    id: raw.filename ? `${raw.filename}-${index}` : `event-${raw.timestamp || index}`,
    filename: raw.filename || null,
    imageUrl: detectionImageUrl(raw.filename),
    timestamp: ts,
    timeLabel: ts ? ts.toLocaleTimeString('en-GB') : '—',
    dateLabel: ts ? ts.toLocaleDateString('en-GB') : '—',
    source: raw.source || 'webcam',
    motion: raw.motion || null,
    mode: raw.mode || 'SAFE',
    context: raw.context || null,
    cameraRisk: Number(raw.camera_risk) || 0,
    radarRisk: Number(raw.radar_risk) || 0,
    fusedRisk: Number(raw.fused_risk) || Number(raw.camera_risk) || 0,
    personCount: Number(raw.person_count) || 0,
    hasWeapon: Boolean(raw.has_weapon),
    weaponType: raw.weapon_type || null,
    confidence: typeof raw.confidence === 'number' ? raw.confidence : null,
    radar: raw.radar || null,
    raw,
  }
}

/**
 * Persistent event history from GET /api/detections (data/monitoring.json).
 * Real data whenever the backend is reachable; forced-demo mode serves a
 * clearly-labeled synthetic list instead.
 */
export function useDetections({ demo = 'auto' } = {}) {
  const [detections, setDetections] = useState([])
  const [status, setStatus] = useState('loading') // loading | ok | error | demo
  const [error, setError] = useState(null)
  const failuresRef = useRef(0)

  const load = useCallback(async () => {
    if (demo === 'forced') {
      setDetections(demoDetections().map(adaptDetection))
      setStatus('demo')
      return
    }
    try {
      const data = await fetchJson(`${API_BASE}/api/detections`)
      const list = Array.isArray(data) ? data : []
      setDetections(list.map(adaptDetection))
      setStatus('ok')
      setError(null)
      failuresRef.current = 0
    } catch (err) {
      failuresRef.current += 1
      if (failuresRef.current >= 2) {
        setStatus('error')
        setError(err.message)
      }
    }
  }, [demo])

  useEffect(() => {
    load()
    const timer = setInterval(load, POLL_MS)
    return () => clearInterval(timer)
  }, [load])

  const clearHistory = useCallback(async () => {
    if (demo === 'forced') return { success: false, error: 'Demo mode' }
    try {
      const response = await fetch(`${API_BASE}/api/detections`, { method: 'DELETE' })
      const data = await response.json().catch(() => ({}))
      if (response.ok && data.success !== false) {
        setDetections([])
        return { success: true }
      }
      return { success: false, error: data.error || `HTTP ${response.status}` }
    } catch (err) {
      return { success: false, error: err.message }
    }
  }, [demo])

  const stats = useMemo(() => {
    const total = detections.length
    let persons = 0
    let weapons = 0
    let danger = 0
    let alert = 0
    for (const d of detections) {
      persons += d.personCount
      if (d.hasWeapon) weapons += 1
      if (d.mode === 'DANGER') danger += 1
      else if (d.mode === 'ALERT') alert += 1
    }
    return { total, persons, weapons, danger, alert }
  }, [detections])

  return { detections, stats, status, error, reload: load, clearHistory, isDemo: status === 'demo' }
}

import { useMemo, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { demoOptionsFromLocation } from '../../design-lab/shared/useAtapisData'
import { useDetections } from './useDetections'

// Investigation Room (חדר חקירה) view model — real persisted detections from
// /api/detections with client-side filtering, plus a selected-event drilldown.

const MODE_OPTIONS = ['ALL', 'SAFE', 'ALERT', 'DANGER']
const SOURCE_OPTIONS = ['ALL', 'webcam', 'dahua']
const RANGE_OPTIONS = [
  { id: 'all', en: 'All time', he: 'כל הזמן', ms: null },
  { id: '24h', en: 'Last 24h', he: '24 שעות', ms: 24 * 3600 * 1000 },
  { id: '7d', en: 'Last 7 days', he: '7 ימים', ms: 7 * 24 * 3600 * 1000 },
  { id: '30d', en: 'Last 30 days', he: '30 ימים', ms: 30 * 24 * 3600 * 1000 },
]

// Reasons for a stored event use only fields persisted with the detection.
export function eventReasons(event, t = (en) => en) {
  const reasons = []
  if (event.personCount > 0) {
    reasons.push({ key: 'person', severity: 'info', source: 'camera', text: t('Person detected', 'זוהה אדם') })
  }
  if (event.motion === 'running') {
    reasons.push({ key: 'running', severity: 'alert', source: 'camera', text: t('Running', 'ריצה') })
  } else if (event.motion) {
    reasons.push({ key: 'motion', severity: 'info', source: 'camera', text: t(event.motion, event.motion) })
  }
  if (event.context && event.context.includes('approach')) {
    reasons.push({ key: 'approach', severity: 'alert', source: 'camera', text: t('Approaching gate', 'התקרבות לשער') })
  }
  if (event.context && event.context.includes('loiter')) {
    reasons.push({ key: 'loiter', severity: 'alert', source: 'camera', text: t('Loitering', 'שהייה ממושכת') })
  }
  if (event.hasWeapon || (event.context && event.context.includes('armed'))) {
    reasons.push({ key: 'armed', severity: 'danger', source: 'camera', text: t('Weapon detected', 'זוהה נשק') })
  }
  if (event.radarRisk > 0) {
    reasons.push({
      key: 'radar', severity: event.radarRisk >= 40 ? 'alert' : 'info', source: 'radar',
      text: t(`Radar contribution (risk ${event.radarRisk})`, `תרומת רדאר (סיכון ${event.radarRisk})`),
    })
  }
  return reasons
}

export function useInvestigationViewModel() {
  const location = useLocation()
  const demoOpts = demoOptionsFromLocation(location.search)
  const detectionsApi = useDetections({ demo: demoOpts.demo })

  const [search, setSearch] = useState('')
  const [mode, setMode] = useState('ALL')
  const [source, setSource] = useState('ALL')
  const [range, setRange] = useState('all')
  const [minRisk, setMinRisk] = useState(0)
  const [selectedId, setSelectedId] = useState(null)

  const filtered = useMemo(() => {
    const rangeMs = RANGE_OPTIONS.find((r) => r.id === range)?.ms ?? null
    const cutoff = rangeMs ? Date.now() - rangeMs : null
    const q = search.trim().toLowerCase()
    return detectionsApi.detections.filter((event) => {
      if (mode !== 'ALL' && event.mode !== mode) return false
      if (source !== 'ALL' && event.source !== source) return false
      if (event.fusedRisk < minRisk) return false
      if (cutoff && event.timestamp && event.timestamp.getTime() < cutoff) return false
      if (q) {
        const haystack = `${event.context || ''} ${event.motion || ''} ${event.mode} ${event.source} ${event.weaponType || ''}`.toLowerCase()
        if (!haystack.includes(q)) return false
      }
      return true
    })
  }, [detectionsApi.detections, search, mode, source, range, minRisk])

  const selected = useMemo(
    () => filtered.find((event) => event.id === selectedId) || filtered[0] || null,
    [filtered, selectedId]
  )

  // Real risk-over-events series (persisted data), oldest → newest.
  const riskSeries = useMemo(
    () =>
      [...filtered]
        .filter((event) => event.timestamp)
        .sort((a, b) => a.timestamp - b.timestamp)
        .map((event) => ({ t: event.timestamp.getTime(), fused: event.fusedRisk, mode: event.mode })),
    [filtered]
  )

  return {
    ...detectionsApi,
    filtered,
    riskSeries,
    filters: {
      search, setSearch,
      mode, setMode, modeOptions: MODE_OPTIONS,
      source, setSource, sourceOptions: SOURCE_OPTIONS,
      range, setRange, rangeOptions: RANGE_OPTIONS,
      minRisk, setMinRisk,
    },
    selected,
    selectedId,
    setSelectedId,
    demo: demoOpts,
  }
}

import { useCallback, useEffect, useState } from 'react'
